internal data class CountryGeoInfo(
    val isoCode: String,
    val countryName: String,
    val cityName: String,
    val latitude: Float,
    val longitude: Float
)

internal fun getCountryGeoInfo(codeTag: String?): CountryGeoInfo {
    return when (codeTag.orEmpty()) {
        "DED-NL" -> CountryGeoInfo(
            isoCode = "NL",
            countryName = "NETHERLANDS",
            cityName = "Amsterdam",
            latitude = 52.25f,
            longitude = 5.30f
        )
        "DED-PL" -> CountryGeoInfo(
            isoCode = "PL",
            countryName = "POLAND",
            cityName = "Warsaw",
            latitude = 52.15f,
            longitude = 19.40f
        )
        "VPS-1" -> CountryGeoInfo(
            isoCode = "DE",
            countryName = "GERMANY",
            cityName = "Frankfurt",
            latitude = 51.10f,
            longitude = 10.40f
        )
        "GHOST" -> CountryGeoInfo(
            isoCode = "NL",
            countryName = "NETHERLANDS • GHOST",
            cityName = "Stealth Relay",
            latitude = 52.25f,
            longitude = 5.30f
        )
        "CF-1", "CF-2", "BPB" -> CountryGeoInfo(
            isoCode = "DE",
            countryName = "GERMANY",
            cityName = "Frankfurt",
            latitude = 51.10f,
            longitude = 10.40f
        )
        else -> CountryGeoInfo(
            isoCode = "FR",
            countryName = "FRANCE",
            cityName = "Paris",
            latitude = 46.60f,
            longitude = 2.40f
        )
    }
}

