    val polygons: List<RealCountryPoly> by lazy {
        RAW_RINGS.mapNotNull { line ->
            val pipe = line.indexOf('|')
            if (pipe <= 0) return@mapNotNull null
            val iso = line.substring(0, pipe)
            val pairs = line.substring(pipe + 1).split(';')
            if (pairs.size < 3) return@mapNotNull null
            val coords = FloatArray(pairs.size * 2)
            var k = 0
            for (p in pairs) {
                val commaIdx = p.indexOf(',')
                if (commaIdx > 0) {
                    coords[k++] = p.substring(0, commaIdx).toFloatOrNull() ?: 0f
                    coords[k++] = p.substring(commaIdx + 1).toFloatOrNull() ?: 0f
                }
            }
            RealCountryPoly(iso = iso, isWater = (iso == "WATER"), latLonPairs = coords.copyOf(k))
        }
    }
}
